import type { Pattern } from "../types";

/**
 * The hard tier.
 *
 * These are not "medium plus more code". They are the structures that separate a
 * candidate who solved the base problem from one who survives the follow-up. Every
 * entry carries a derivation (how to reach it at a whiteboard, from the brute force)
 * and a proof sketch (what to say when they ask you to justify it), because in a hard
 * round the implementation is the easy half.
 */
